// FWD v0.05.00: while charging the blue light blinks (the extra redraws are fine on the charger)
#define LIGHT_BLINK_MS 1000  // 1 s on, 1 s off
static AppTimer *s_light_blink_timer = NULL;
static bool      s_light_blink_on = true;

static void light_blink_cb(void *data) {
  s_light_blink_on = !s_light_blink_on;
  s_light_blink_timer = app_timer_register(LIGHT_BLINK_MS, light_blink_cb, NULL);
  if (s_scene) layer_mark_dirty(s_scene);
}

static void light_blink_update(void) {  // blink only while the light shows charging
  bool want = s_light_battery && s_charging;
  if (want && !s_light_blink_timer) {
    s_light_blink_on = true;
    s_light_blink_timer = app_timer_register(LIGHT_BLINK_MS, light_blink_cb, NULL);
  } else if (!want && s_light_blink_timer) {
    app_timer_cancel(s_light_blink_timer);
    s_light_blink_timer = NULL;
    s_light_blink_on = true;
  }
}

